import { useState } from 'react';
import { useEffect } from 'react';
import './Profile.css';

function Profile({ userPage, sameUser, activeUser}) {
    const friends = (activeUser?.friendsRequest?.includes(userPage.email)) && (activeUser?.friends?.includes(userPage.email));
    
    const addFriend = async()=>{

            
        try {
            const response = await fetch('http://localhost:8080/api/users/' + activeUser.email + '/friends', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${activeUser.token}`
                },   
                body: JSON.stringify({
                    // Include only the fields to be updated
                    // (e.g., name, email, etc.)
                    // Do not include the token
                    // For example:
                    newRequestEmail: userPage.email
                })
            });

            if (!response.ok) {
                throw new Error('Failed to delete post');
            }

            // Post deleted successfully
        } catch (error) {
            console.error('Error deleting post:', error);
            // Handle error (e.g., display error message to the user)
        }

    }

    return (

        <div className="Profile">
            <div className="images">
                <img src="/images/back.jpeg" alt="" className="cover" />
                <img src={userPage?.picture} alt="" className="profilePic" />
                <div className="profileContainer">
                    <div className="uInfo">
                        <div className="center">
                            <span>{userPage?.displayName}</span>
                            {!friends && !sameUser && <button onClick={addFriend}>add friend</button>}
                        </div>

                    </div>
                </div>
            </div>
        </div>
    



    );
}

export default Profile;
